import itertools

def get_next_config(config, k):
    k_idx = k - 1
    metal = config[k_idx]
    start = k_idx
    while start > 0 and config[start-1] == metal:
        start -= 1
    end = k_idx
    while end < len(config) - 1 and config[end+1] == metal:
        end += 1
    block = config[start : end+1]
    remaining = config[:start] + config[end+1:]
    return block + remaining

def count_transitions(config):
    transitions = 0
    for i in range(len(config) - 1):
        if config[i] != config[i+1]:
            transitions += 1
    return transitions

def get_configs(N):
    # Get all unique permutations of N 'A's and N 'C's
    # Using a combination approach to pick indices of 'A'
    from itertools import combinations
    total = 2 * N
    indices = range(total)
    for a_indices in combinations(indices, N):
        config = ['C'] * total
        for i in a_indices:
            config[i] = 'A'
        yield tuple(config)

def check_k_works(N, k):
    for config in get_configs(N):
        seen = set()
        current = config
        reached_goal = False
        # Limit the number of steps to avoid infinite loops, but seen should handle it
        while current not in seen:
            seen.add(current)
            if count_transitions(current) <= 1:
                reached_goal = True
                break
            current = get_next_config(current, k)
        if not reached_goal:
            return False
    return True

for N in range(2, 8):
    valid_ks = []
    for k in range(1, 2*N + 1):
        if check_k_works(N, k):
            valid_ks.append(k)
    print(f"N={N}: k_set={valid_ks}")

